     1→<script lang="ts">
     2→	import 'pdfjs-dist/web/pdf_viewer.css';
     3→	import type { getDocument, TextItem } from 'pdfjs-dist/types/src/display/api';
     4→	import type { GlobalWorkerOptions, TextLayer } from 'pdfjs-dist';
     5→	import type { PageData } from './$types';
     6→
     7→	let { data }: { data: PageData } = $props();
     8→
     9→	let pdfjs: {
    10→		getDocument: typeof getDocument;
    11→		GlobalWorkerOptions: typeof GlobalWorkerOptions;
    12→		TextLayer: typeof TextLayer;
    13→	} | null = null;
    14→
    15→	async function loadPdfJs() {
    16→		if (!pdfjs) {
    17→			const { getDocument, GlobalWorkerOptions, TextLayer } = await import('pdfjs-dist');
    18→			const worker = await import('pdfjs-dist/build/pdf.worker.mjs?url');
    19→			GlobalWorkerOptions.workerSrc = worker.default;
    20→			pdfjs = { getDocument, GlobalWorkerOptions, TextLayer };
    21→		}
    22→		return pdfjs;
    23→	}
    24→
    25→	let pdfFile = $state<File | null>(null);
    26→	let pdfUrl = $state<string | null>(null);
    27→
    28→	// Store page data for search
    29→	interface PageTextData {
    30→		pageWrapper: HTMLElement;
    31→		viewport: { width: number; height: number; scale: number };
    32→		textItems: Array<{
    33→			str: string;
    34→			transform: number[];
    35→			width: number;
    36→			height: number;
    37→		}>;
    38→	}
    39→	let pagesData: PageTextData[] = [];
    40→
    41→	// Search state
    42→	let searchQuery = $state<string>('');
    43→	let matchCount = $state<number>(0);
    44→	let currentMatchIndex = $state<number>(0);
    45→	let highlightElements: HTMLElement[] = [];
    46→	let searchInputEl = $state<HTMLInputElement | null>(null);
    47→	let matchCase = $state<boolean>(false);
    48→	let matchWholeWord = $state<boolean>(false);
    49→
    50→	function performSearch() {
    51→		// Clear previous highlights
    52→		document.querySelectorAll('.search-highlight-overlay').forEach((el) => el.remove());
    53→		highlightElements = [];
    54→		matchCount = 0;
    55→		currentMatchIndex = 0;
    56→
    57→		if (!searchQuery.trim() || pagesData.length === 0) return;
    58→
    59→		const query = matchCase ? searchQuery : searchQuery.toLowerCase();
    60→
    61→		// Search through each page's text data
    62→		pagesData.forEach((pageData) => {
    63→			// Build combined text with character position mapping
    64→			interface CharInfo {
    65→				itemIndex: number;
    66→				charIndex: number;
    67→			}
    68→			const charMap: CharInfo[] = [];
    69→			let combinedText = '';
    70→
    71→			pageData.textItems.forEach((item, itemIndex) => {
    72→				for (let i = 0; i < item.str.length; i++) {
    73→					charMap.push({ itemIndex, charIndex: i });
    74→				}
    75→				combinedText += item.str;
    76→			});
    77→
    78→			// Find matches
    79→			const textToSearch = matchCase ? combinedText : combinedText.toLowerCase();
    80→			let searchPos = 0;
    81→
    82→			while (true) {
    83→				const matchIndex = textToSearch.indexOf(query, searchPos);
    84→				if (matchIndex === -1) break;
    85→
    86→				// Check whole word boundary if enabled
    87→				if (matchWholeWord) {
    88→					const charBefore = matchIndex > 0 ? textToSearch[matchIndex - 1] : ' ';
    89→					const charAfter =
    90→						matchIndex + query.length < textToSearch.length
    91→							? textToSearch[matchIndex + query.length]
    92→							: ' ';
    93→					const isWordBoundaryBefore = !/\w/.test(charBefore);
    94→					const isWordBoundaryAfter = !/\w/.test(charAfter);
    95→
    96→					if (!isWordBoundaryBefore || !isWordBoundaryAfter) {
    97→						searchPos = matchIndex + 1;
    98→						continue;
    99→					}
   100→				}
   101→
   102→				const matchEnd = matchIndex + query.length;
   103→				matchCount++;
   104→
   105→				// Find which text items this match spans
   106→				const startChar = charMap[matchIndex];
   107→				const endChar = charMap[matchEnd - 1];
   108→
   109→				if (!startChar || !endChar) {
   110→					searchPos = matchIndex + 1;
   111→					continue;
   112→				}
   113→
   114→				// Create highlights for each text item in this match
   115→				for (let itemIdx = startChar.itemIndex; itemIdx <= endChar.itemIndex; itemIdx++) {
   116→					const item = pageData.textItems[itemIdx];
   117→					const transform = item.transform;
   118→
   119→					// Transform matrix: [scaleX, skewY, skewX, scaleY, translateX, translateY]
   120→					const x = transform[4];
   121→					const y = transform[5];
   122→					const fontHeight = Math.abs(transform[3]); // scaleY = font height in PDF units
   123→
   124→					// Calculate the portion of this item that's highlighted
   125→					let highlightStartChar = 0;
   126→					let highlightEndChar = item.str.length;
   127→
   128→					if (itemIdx === startChar.itemIndex) {
   129→						highlightStartChar = startChar.charIndex;
   130→					}
   131→					if (itemIdx === endChar.itemIndex) {
   132→						highlightEndChar = endChar.charIndex + 1;
   133→					}
   134→
   135→					// item.width is already the total width in PDF units
   136→					const charWidth = item.width / item.str.length;
   137→					const highlightX = x + highlightStartChar * charWidth;
   138→					const highlightWidth = (highlightEndChar - highlightStartChar) * charWidth;
   139→
   140→					// Create highlight overlay
   141→					const highlight = document.createElement('div');
   142→					highlight.className = 'search-highlight-overlay';
   143→					highlight.dataset.matchIndex = String(matchCount - 1);
   144→
   145→					// Position in PDF coordinates, then scale to viewport
   146→					const scale = pageData.viewport.scale;
   147→					highlight.style.left = `${highlightX * scale}px`;
   148→					highlight.style.bottom = `${y * scale}px`;
   149→					highlight.style.width = `${Math.max(highlightWidth * scale, 4)}px`;
   150→					highlight.style.height = `${fontHeight * scale}px`;
   151→
   152→					pageData.pageWrapper.appendChild(highlight);
   153→					highlightElements.push(highlight);
   154→				}
   155→
   156→				searchPos = matchIndex + 1;
   157→			}
   158→		});
   159→
   160→		if (highlightElements.length > 0) {
   161→			scrollToMatch(0);
   162→		}
   163→	}
   164→
   165→	function scrollToMatch(index: number) {
   166→		// Remove current highlight styling
   167→		highlightElements.forEach((el) => el.classList.remove('current-match'));
   168→
   169→		if (matchCount === 0) return;
   170→
   171→		currentMatchIndex = ((index % matchCount) + matchCount) % matchCount;
   172→
   173→		// Find all highlights for this match and mark them as current
   174→		const currentHighlights = highlightElements.filter(
   175→			(el) => el.dataset.matchIndex === String(currentMatchIndex)
   176→		);
   177→
   178→		currentHighlights.forEach((el) => el.classList.add('current-match'));
   179→
   180→		if (currentHighlights.length > 0) {
   181→			currentHighlights[0].scrollIntoView({ behavior: 'smooth', block: 'center' });
   182→		}
   183→	}
   184→
   185→	function nextMatch() {
   186→		scrollToMatch(currentMatchIndex + 1);
   187→	}
   188→
   189→	function prevMatch() {
   190→		scrollToMatch(currentMatchIndex - 1);
   191→	}
   192→
   193→	function handleSearchKeydown(event: KeyboardEvent) {
   194→		if (event.key === 'Escape') {
   195→			searchQuery = '';
   196→			performSearch();
   197→		}
   198→	}
   199→
   200→	function toggleMatchCase() {
   201→		matchCase = !matchCase;
   202→		performSearch();
   203→	}
   204→
   205→	function toggleMatchWholeWord() {
   206→		matchWholeWord = !matchWholeWord;
   207→		performSearch();
   208→	}
   209→
   210→	$effect(() => {
   211→		const hasPdf = Boolean(pdfUrl);
   212→		function onKeydown(e: KeyboardEvent) {
   213→			// Cmd+f: Focus search (always prevent browser's native find dialog)
   214→			if ((e.metaKey || e.ctrlKey) && e.key === 'f') {
   215→				e.preventDefault();
   216→				if (hasPdf) {
   217→					searchInputEl?.focus();
   218→					searchInputEl?.select();
   219→				}
   220→			}
   221→			// Cmd+g: Next match
   222→			if ((e.metaKey || e.ctrlKey) && e.key === 'g' && !e.shiftKey && !e.altKey) {
   223→				if (hasPdf && matchCount > 0) {
   224→					e.preventDefault();
   225→					nextMatch();
   226→				}
   227→			}
   228→			// Cmd+Shift+g: Previous match
   229→			if ((e.metaKey || e.ctrlKey) && e.key === 'g' && e.shiftKey && !e.altKey) {
   230→				if (hasPdf && matchCount > 0) {
   231→					e.preventDefault();
   232→					prevMatch();
   233→				}
   234→			}
   235→			// Cmd+Opt+c: Toggle match case
   236→			if ((e.metaKey || e.ctrlKey) && e.altKey && e.code === 'KeyC') {
   237→				if (hasPdf) {
   238→					e.preventDefault();
   239→					toggleMatchCase();
   240→				}
   241→			}
   242→			// Cmd+Opt+w: Toggle match whole word
   243→			if ((e.metaKey || e.ctrlKey) && e.altKey && e.code === 'KeyW') {
   244→				if (hasPdf) {
   245→					e.preventDefault();
   246→					toggleMatchWholeWord();
   247→				}
   248→			}
   249→		}
   250→		document.addEventListener('keydown', onKeydown, true);
   251→		return () => document.removeEventListener('keydown', onKeydown, true);
   252→	});
   253→
   254→	async function handleFileChange(event: Event) {
   255→		if (!(event.target instanceof HTMLInputElement)) return;
   256→		const pdfjs = await loadPdfJs();
   257→		const input = event.target;
   258→
   259→		const container = document.getElementById('pdf-container');
   260→
   261→		if (input.files && input.files[0] && container) {
   262→			pdfFile = input.files[0];
   263→			pdfUrl = URL.createObjectURL(pdfFile);
   264→			container.innerHTML = '';
   265→			pagesData = [];
   266→			searchQuery = '';
   267→			matchCount = 0;
   268→
   269→			const fileReader = new FileReader();
   270→
   271→			fileReader.onload = async (e) => {
   272→				if (!e.target || !(e.target.result instanceof ArrayBuffer)) return;
   273→				const pdf = await pdfjs.getDocument({ data: new Uint8Array(e.target.result) }).promise;
   274→
   275→				for (let pageNum = 1; pageNum <= pdf.numPages; pageNum++) {
   276→					const page = await pdf.getPage(pageNum);
   277→					const viewport = page.getViewport({ scale: 1.5 });
   278→
   279→					// Create page wrapper
   280→					const pageWrapper = document.createElement('div');
   281→					pageWrapper.className = 'page-wrapper';
   282→					pageWrapper.style.width = `${viewport.width}px`;
   283→					pageWrapper.style.height = `${viewport.height}px`;
   284→
   285→					// Create and render canvas
   286→					const canvas = document.createElement('canvas');
   287→					const context = canvas.getContext('2d');
   288→
   289→					if (!context) return;
   290→
   291→					canvas.height = viewport.height;
   292→					canvas.width = viewport.width;
   293→
   294→					await page.render({ canvasContext: context, viewport }).promise;
   295→					pageWrapper.appendChild(canvas);
   296→
   297→					// Create and render text layer
   298→					const textLayerDiv = document.createElement('div');
   299→					textLayerDiv.className = 'textLayer';
   300→					const PDF_TO_CSS_UNITS = 96 / 72;
   301→					textLayerDiv.style.setProperty(
   302→						'--scale-factor',
   303→						(viewport.scale * PDF_TO_CSS_UNITS).toString()
   304→					);
   305→
   306→					const textContent = await page.getTextContent();
   307→
   308→					// Store text data for search
   309→					const textItems = textContent.items
   310→						.filter((item): item is TextItem => 'str' in item && item.str.length > 0)
   311→						.map((item) => ({
   312→							str: item.str,
   313→							transform: item.transform,
   314→							width: item.width,
   315→							height: item.height
   316→						}));
   317→
   318→					pagesData.push({
   319→						pageWrapper,
   320→						viewport: { width: viewport.width, height: viewport.height, scale: viewport.scale },
   321→						textItems
   322→					});
   323→
   324→					const textLayer = new pdfjs.TextLayer({
   325→						textContentSource: textContent,
   326→						container: textLayerDiv,
   327→						viewport: viewport
   328→					});
   329→					await textLayer.render();
   330→					pageWrapper.appendChild(textLayerDiv);
   331→
   332→					container.appendChild(pageWrapper);
   333→				}
   334→			};
   335→			fileReader.readAsArrayBuffer(pdfFile);
   336→		}
   337→	}
   338→</script>
